    val fail = IntArray(m) { 0 }
    for (i in 1 until m) {
        var j = fail[i - 1]
        while (j > 0 && s[i] != s[j]) {
            j = fail[j - 1]
        }
        if (s[i] == s[j]) {
            j++
        }
        fail[i] = j
    }

    // Build transition table for KMP automaton
    val trans = Array(m + 1) { IntArray(2) { 0 } }
    for (state in 0..m) {
        for (c in 0..1) {
            if (state < m && s[state] - '0' == c) {
                trans[state][c] = state + 1
            } else {
                if (state == 0) {
                    trans[state][c] = 0
                } else {
                    trans[state][c] = trans[fail[state - 1]][c]
                }
            }
        }
    }

    // DP[i][state][started] = number of ways
    val dp = Array(n + 1) { Array(m + 1) { LongArray(2) { 0 } } }
    dp[0][0][0] = 1

    for (i in 0 until n) {
        for (state in 0..m) {
            for (started in 0..1) {
                val cnt = dp[i][state][started]
                if (cnt == 0L) continue
                for (c in 0..1) {
                    val next_state = trans[state][c]
                    val next_started = if (started == 1 || next_state > 0) 1 else 0
                    if (next_state <= m) {
                        dp[i + 1][next_state][next_started] = (dp[i + 1][next_state][next_started] + cnt) % 1000000007
                    }
                }
            }
        }
    }

    var ans = 0L
    for (state in 0..m) {
        ans = (ans + dp[n][state][1]) % 1000000007
    }
